import React, { useState, useEffect, useMemo, useRef } from "react";
import { Trophy, Minus, X, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { base44 } from "@/api/base44Client";
import { getEndReason } from "@/lib/gameEndReason";
import ShareOnXButton from "./ShareOnXButton";
import ShareOnFacebookButton from "./ShareOnFacebookButton";
import DownloadVictoryCardButton from "./DownloadVictoryCardButton";
import ReportContestButton from "@/components/disputes/ReportContestButton";
import RematchControls from "./RematchControls";
import { trackPixelEvent } from "@/lib/metaPixel";

export default function SettlementState({ match, game, userId, onReturn, onRematchAccepted }) {
  const free=match.play_mode==='free';
  const [opponentName, setOpponentName] = useState("Opponent");
  const [winnerName, setWinnerName] = useState("You");
  const [returning, setReturning] = useState(false);
  const rematchRef = useRef(null);
  // Guards against firing "Match Completed" more than once for the same
  // match if this component re-renders/remounts while still showing it.
  const trackedMatchIdRef = useRef(null);

  const won = match.winner_id === userId;
  const draw = match.result === "draw";
  const isP1 = match.player1_id === userId;
  const opponentId = isP1 ? match.player2_id : match.player1_id;

  useEffect(() => {
    if (trackedMatchIdRef.current === match.id) return;
    trackedMatchIdRef.current = match.id;
    trackPixelEvent("Match Completed", {
      value: match.wager_amount,
      currency: "USD",
      result: draw ? "draw" : won ? "win" : "loss",
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [match.id]);

  useEffect(() => {
    const load = async () => {
      const ids = [userId, opponentId].filter(Boolean);
      if (ids.length === 0) return;
      const { data } = await base44.functions.invoke("getUserDisplayNames", { userIds: ids });
      if (opponentId) setOpponentName(data?.names?.[opponentId] || "Opponent");
      if (userId) setWinnerName(data?.names?.[userId] || "You");
    };
    load();
  }, [userId, opponentId]);

  const endReason = useMemo(() => getEndReason(game), [game]);

  const handleReturn = async () => {
    if (returning) return;
    setReturning(true);
    try {
      await rematchRef.current?.leave();
      await onReturn?.();
    } finally {
      setReturning(false);
    }
  };


  return (
    <div className="space-y-5 lg:space-y-3 text-center py-4">
      <div
        className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto ${
          draw ? "bg-white/10" : won ? "gold-gradient" : "bg-red-500/10"
        }`}
      >
        {draw ? (
          <Minus size={26} className="text-white/50" />
        ) : won ? (
          <Trophy size={26} className="text-black" />
        ) : (
          <X size={26} className="text-red-400" />
        )}
      </div>
      <div>
        <p className={`text-2xl font-extrabold ${draw ? "text-white/50" : won ? "text-[#C9A84C]" : "text-red-400"}`}>
          {draw ? "Draw" : won ? "Victory!" : "Defeat"}
        </p>
        <p className="text-white/50 text-xs font-semibold uppercase tracking-widest mt-1">{endReason}</p>
        <p className="text-white/40 text-sm mt-1">
          {free ? 'Free game completed.' : draw
            ? "Entry amounts and service fees have been refunded"
            : won
            ? `You won $${(match.wager_amount * 2).toFixed(2)}`
            : `You lost $${match.wager_amount.toFixed(2)}`}
        </p>
      </div>
      {!free && !draw && won && (
        <div className="rounded-2xl bg-[#C9A84C]/5 border border-[#C9A84C]/20 p-4">
          <p className="text-[10px] text-[#C9A84C]/60 uppercase tracking-widest mb-1">Winner Award — Full Contest Entry Amounts</p>
          <p className="text-2xl font-extrabold text-[#C9A84C]">+${(match.wager_amount * 2).toFixed(2)}</p>
        </div>
      )}
      <p className="text-xs text-white/40">{free ? "This game counts toward your rating." : won && !draw ? "Winner awards follow the standard report-window hold before becoming available. A rematch needs a separate available balance." : "Wallet updated"}</p>
      <div className="space-y-2">
        <RematchControls ref={rematchRef} match={match} opponentName={opponentName} onAccepted={onRematchAccepted} />
        <Button
          onClick={handleReturn}
          disabled={returning}
          className="w-full h-12 rounded-2xl font-bold gold-gradient text-black hover:opacity-90 disabled:opacity-60"
        >
          {returning ? <Loader2 size={16} className="animate-spin mr-2" /> : null}
          {returning ? "Returning..." : "Challenge Someone Else"}
        </Button>
        {won && !free && (
          <>
            <ShareOnXButton match={match} game={game} winnerName={winnerName} opponentName={opponentName} endReason={endReason} />
            <ShareOnFacebookButton match={match} game={game} winnerName={winnerName} opponentName={opponentName} endReason={endReason} />
            <DownloadVictoryCardButton match={match} game={game} winnerName={winnerName} opponentName={opponentName} endReason={endReason} />
          </>
        )}
      </div>

      <div className="flex justify-center pt-1">
        <ReportContestButton matchId={match.id} gameId={game?.id} />
      </div>
    </div>
  );
}

